// Diagnostic ONLY: replace the already-computed block0 outputs with captured HLSL
// outputs to distinguish prefix drift from downstream wiring/math. Never a game backend.
#include "hip_reference_network.h"
using namespace hip_reference;
int main(int argc,char**argv){try{if(argc!=7&&argc!=8){puts("replay_prefix ASSETS MODULES INPUT NOISE OUTPUT HLSL_CAPTURE_PREFIX");return 2;}Options o;o.assets=argv[1];o.modules=argv[2];o.width=1600;o.height=1024;o.post_shift=3;o.wmma=o.wave=o.tiled=o.pooled=o.fast_c32=o.fused_c32=o.fast_mh=o.fast_deep=o.fast_prefix=o.fast_vit=true;o.skip_blocks={42,43,46};auto load=[](const std::string&p){auto b=ReadBytes(p);if(b.size()%4)throw std::runtime_error("f32 alignment");std::vector<float>v(b.size()/4);memcpy(v.data(),b.data(),b.size());return v;};auto input=load(argv[3]),noise=load(argv[4]),down=load(std::string(argv[6])+"-pre-down.bin");auto bytes=ReadBytes(std::string(argv[6])+"-pre-main8.bin");std::vector<float>main(bytes.size());for(size_t i=0;i<bytes.size();i++){U b=static_cast<unsigned char>(bytes[i]),e=(b>>3)&15,m=b&7;if((b&127)==127)throw std::runtime_error("nonfinite captured FP8");float v=e?std::ldexp(1.f+m/8.f,int(e)-7):m/512.f;main[i]=b&128?-v:v;}
 std::vector<float>main4,down4;if(argc==8){auto b4=ReadBytes(std::string(argv[6])+"-block4-main8.bin");if(b4.size()!=800ull*520*32)throw std::runtime_error("block4 capture shape");main4.resize(800ull*512*32);for(size_t i=0;i<main4.size();i++){U b=static_cast<unsigned char>(b4[i+4ull*800*32]),e=(b>>3)&15,m=b&7;float v=e?std::ldexp(1.f+m/8.f,int(e)-7):m/512.f;main4[i]=b&128?-v:v;}down4=load(std::string(argv[6])+"-block4-down.bin");}
 Network net(o);net.SetStageObserver([&](const std::string&name,void*p,size_t n){const std::vector<float>*v=name=="pre-down"?&down:name=="block0"?&main:argc==8&&name=="block4"?&main4:argc==8&&name=="block4-down"?&down4:nullptr;if(v){if(v->size()*4!=n)throw std::runtime_error("replay shape mismatch");net.Runtime().Check(net.Runtime().hipMemcpy(p,v->data(),n,1),"diagnostic captured state upload");printf("REPLAY %s floats=%zu\n",name.c_str(),v->size());}});auto out=net.Infer(input,noise);std::ofstream f(argv[5],std::ios::binary);if(!f.write(reinterpret_cast<const char*>(out.data()),out.size()*4))throw std::runtime_error("write");puts("Diagnostic replay complete; this is not normal end-to-end inference validation.");return 0;}catch(const std::exception&e){fprintf(stderr,"replay failed: %s\n",e.what());return 1;}}
